// Maximum overlap (penetration) between the ball and a brick along either axis.
function penetration(ball, brick) {
  const ox = Math.min(
    ball.x + ball.r - brick.x,
    brick.x + brick.w - (ball.x - ball.r),
  );
  const oy = Math.min(
    ball.y + ball.r - brick.y,
    brick.y + brick.h - (ball.y - ball.r),
  );
  // rough scalar of "how deep" the overlap is
  return ox + oy;
}
